// src/hooks/useFeedPosts.ts
function useFeedPosts({
  chainId,
  topic,
  maxMessages = 50,
  enabled = true,
  sender
}) {
  const normalizedTopic = useMemo(
    () => normalizeFeedTopic(topic),
    [topic]
  );
  const filter = useMemo(() => {
    const baseFilter = {
      appAddress: NULL_ADDRESS,
      topic: normalizedTopic
    };
    if (sender) {
      return {
        ...baseFilter,
        maker: sender
      };
    }
    return baseFilter;
  }, [normalizedTopic, sender]);
  const { count: totalCount, isLoading: isLoadingCount } = useNetMessageCount({
    chainId,
    filter,
    enabled
  });
  const startIndex = maxMessages === 0 ? totalCount : totalCount > maxMessages ? totalCount - maxMessages : 0;
  const { messages, isLoading: isLoadingMessages } = useNetMessages({
    chainId,
    filter,
    startIndex,
    endIndex: totalCount,
    enabled: enabled && totalCount > 0
    // Guard to prevent query when no messages
  });
  return {
    posts: messages,
    totalCount,
    isLoading: isLoadingCount || isLoadingMessages
    // Note: No error field returned (matches useTopicFeed API)
  };
}

